{
  "a_sentences": [
    {
      "a_text": "Die Beschwerdeführerin stellte vor dem Schiedsgericht dasselbe Rechtsbegehren wie der Versicherte vor dem kantonalen Verwaltungsgericht, lautend auf die Verpflichtung der Beschwerdegegnerin zur Bezahlung der für den Versicherten in den Jahren 2021 und 2022 erbrachten Pflegeleistungen von Fr. 91'270.05 (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Dieser Umstand erweckt den Anschein, dass die Beschwerdeführerin den dem Versicherten zustehenden Anspruch ein weiteres Mal auf dem schiedsgerichtlichen Weg geltend machen wollte (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Gemäss Art. 89 KVG entscheidet ein Schiedsgericht Streitigkeiten zwischen Versicherern und Leistungserbringern (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die sachliche Zuständigkeit des Schiedsgerichts ist für alle Streitigkeiten zwischen Krankenversicherern und Leistungserbringern zu bejahen, wenn und soweit sie Rechtsbeziehungen zum Gegenstand haben, die sich aus dem KVG ergeben oder aufgrund des KVG eingegangen worden sind (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Auf die Zuständigkeit des Schiedsgerichts hat keinen Einfluss, ob das System des Tiers payant oder des Tiers garant gilt (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Bundesgericht hält fest, dass die Vorinstanz auf die Klage zu Recht nicht eingetreten ist, da die Beschwerdeführerin lediglich an die Stelle des Versicherten getreten ist und die Rechtsnatur der Anspruchsgrundlage sich nicht geändert hat (P6).",
      "b_propositions": ["P6"]
    }
  ]
}
